import os
import hashlib
import hmac
import time
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('APP_SECRET', 'dev-secret-key')
app.config['DB_PATH'] = os.environ.get('DB_PATH', '/data/app.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DB_PATH'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_session_token(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.cookies.get('session_token')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        # HMAC verification of session token
        parts = token.split('.')
        if len(parts) != 3:
            return jsonify({'error': 'invalid token'}), 401
        user_id, timestamp, sig = parts
        expected = hmac.new(app.config['SECRET_KEY'].encode(),
                           f'{user_id}.{timestamp}'.encode(), hashlib.sha256).hexdigest()[:16]
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 401
        if time.time() - float(timestamp) > 86400:
            return jsonify({'error': 'expired'}), 401
        g.current_user_id = user_id
        return f(*args, **kwargs)
    return decorated

@app.route('/api/documents/search')
@verify_session_token
def search_documents():
    query = request.args.get('q', '')
    doc_type = request.args.get('type', 'all')
    owner = g.current_user_id

    # Build search query with owner filter for access control
    base_query = "SELECT id, title, snippet, created_at FROM documents WHERE owner_id = ?"
    params = [owner]

    if query:
        base_query += " AND (title LIKE ? OR content LIKE ?)"
        params.extend([f'%{query}%', f'%{query}%'])

    if doc_type != 'all':
        # Filter by document type - constructed from user input
        base_query += f" AND doc_type = '{doc_type}'"

    base_query += " ORDER BY created_at DESC LIMIT 50"

    db = get_db()
    try:
        results = db.execute(base_query, params).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'results': [], 'error': 'search failed'}), 500

@app.route('/api/documents/<int:doc_id>')
@verify_session_token
def get_document(doc_id):
    db = get_db()
    doc = db.execute(
        "SELECT * FROM documents WHERE id = ? AND owner_id = ?",
        [doc_id, g.current_user_id]
    ).fetchone()
    if not doc:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(doc))

@app.route('/api/documents', methods=['POST'])
@verify_session_token
def create_document():
    data = request.get_json()
    if not data or 'title' not in data:
        return jsonify({'error': 'title required'}), 400
    db = get_db()
    db.execute(
        "INSERT INTO documents (title, content, doc_type, owner_id, created_at) VALUES (?, ?, ?, ?, ?)",
        [data['title'], data.get('content', ''), data.get('type', 'note'),
         g.current_user_id, time.time()]
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/api/admin/stats')
@verify_session_token
def admin_stats():
    # Only user_id '1' is admin
    if g.current_user_id != '1':
        return jsonify({'error': 'forbidden'}), 403
    db = get_db()
    count = db.execute("SELECT COUNT(*) as c FROM documents").fetchone()
    users = db.execute("SELECT COUNT(DISTINCT owner_id) as c FROM documents").fetchone()
    return jsonify({'total_docs': count['c'], 'total_users': users['c']})

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
